# Generated by `plaudon-release packaging render` from the artifact the release
# workflow built. The version and the SHA-256 are read off that file; nothing
# here is typed by hand, and the renderer refuses to emit a cask that still
# contains a placeholder. Edit packaging/homebrew/plaudon.rb.tmpl instead.
cask "plaudon" do
  version "0.0.0"
  sha256 "3e479a00a860e526673e4bd7d178a7a1e341899ac29391956c8bd4edfce5fc0f"

  url "https://github.com/spdrman/plaudon/releases/download/v#{version}/Plaudon-#{version}-macos-arm64.zip",
      verified: "github.com/spdrman/plaudon/"
  name "Plaudon"
  desc "Local-first desktop app for importing, transcribing and reviewing recordings"
  homepage "https://github.com/spdrman/plaudon"

  livecheck do
    url :url
    strategy :github_latest
  end

  # Apple Silicon only: there is no Intel build, and the bundle's own
  # LSMinimumSystemVersion is 13.0, which is what the macOS
  # requirement below is derived from.
  depends_on arch: :arm64
  # The PLAUD source drives the vendor's npm-distributed CLI, so Node.js is a
  # real runtime dependency of that feature rather than a build tool.
  depends_on formula: "node"
  depends_on macos: :ventura

  app "Plaudon.app"
  # The guided PLAUD sign-in helper ships inside the bundle; this is what puts
  # it on the PATH as `plaudon-setup-plaud`.
  binary "#{appdir}/Plaudon.app/Contents/Resources/plaudon-setup-plaud"

  # The official PLAUD Cloud CLI is an npm package, so it is not part of this
  # cask's download and Homebrew cannot depend on it. It is installed here, at
  # the one version this build drives — the application fails closed on every
  # other version, so installing a different one would only move the failure
  # later.
  #
  # The step is skipped when a `plaud` already exists in Homebrew's prefix,
  # including an older one: replacing a CLI somebody else installed is
  # `plaudon-setup-plaud`'s job, where it is announced and explained. Failure
  # is not fatal — the application still works on local files — and the
  # caveats say what to run when it happens.
  postflight_steps do
    unless_path_exists "bin/plaud", base: :homebrew_prefix do
      run "bin/npm",
          base:           :homebrew_prefix,
          args:           ["install", "--global", "@plaud-ai/cli@0.3.15"],
          network_access: true,
          must_succeed:   false,
          print_stdout:   true
    end
  end

  uninstall quit: "app.plaudon.desktop"

  # `brew uninstall --zap` removes your library as well. Plain uninstall does
  # not touch it.
  zap trash: [
    "~/Library/Application Support/app.plaudon.desktop",
    "~/Library/Caches/app.plaudon.desktop",
    "~/Library/Preferences/app.plaudon.desktop.plist",
    "~/Library/Saved Application State/app.plaudon.desktop.savedState",
  ]

  caveats <<~EOS
    Plaudon 0.0.0 is UNSIGNED and NOT NOTARIZED.

    The bundle is built without an Apple Developer ID certificate and is never
    sent to Apple for notarization, so Gatekeeper will refuse to open it. You
    can see that for yourself: the release carries a signing report that says
    `signature_status` and `notarization_status` in its own words.

    Homebrew quarantines what it downloads, so after installing either

        xattr -dr com.apple.quarantine /Applications/Plaudon.app

    or install without the quarantine attribute in the first place:

        brew install --cask --no-quarantine plaudon

    Running unsigned software is a decision only you can make, and this cask
    does not make it for you by stripping the attribute behind your back.

    The PLAUD source needs the official PLAUD Cloud CLI
    (`@plaud-ai/cli`), which is an npm package and not part of this cask's
    download. Unless a `plaud` was already in Homebrew's prefix, installing this
    cask ran `npm install -g @plaud-ai/cli@0.3.15` for you — a global
    npm install, outside Homebrew's prefix bookkeeping, which
    `brew uninstall --cask plaudon` will not undo. Remove it yourself with
    `npm uninstall -g @plaud-ai/cli` if you want it gone.

    0.3.15 is the only version this build drives; it fails closed on
    anything else, including a `plaud` that was already installed. To check that,
    install it if it is missing or wrong, and sign in to your own PLAUD account:

        plaudon-setup-plaud

    That runs the vendor's own `plaud login` in your browser and confirms it
    with `plaud me`. Plaudon never sees your PLAUD password, and it cannot sign
    you out again.

    Local-only Mode is on from the first launch and blocks every outbound
    request, including the PLAUD source. Turn it off when you want the
    application to reach the network at all.

    No warranty of any kind: this is MIT-licensed software you chose to run.
  EOS
end
